#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
_WIZARD_CONFIGURED=0
_WIZARD_ROOT=""; _WIZARD_ENV_FILE=""; _WIZARD_REPO=""
WRITTEN_ENV=()    # successful KEY and destination records
WRITTEN_SECRET=() # successful secret NAME and destination records
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _env_file MODE [KEY] is the shared boundary for saved values. Missing reads
# return 1; unsafe destinations and I/O errors return 2. The explicit value
# payload uses FD 3; Python source uses stdin. Python still inherits the shell's
# exported environment. All filesystem access starts at the confirmed root.
_env_file() {
  if [[ "$1" != check ]]; then _require_destinations || return "$?"; fi
  python3 -I - "$_WIZARD_ROOT" "$ENV_FILE" "$1" "${2-}" 3<&0 <<'PY'
import errno
import os
import re
import secrets
import stat
import sys


def identity(info):
    return (info.st_dev, info.st_ino, info.st_mode, info.st_uid, info.st_gid,
            info.st_size, info.st_mtime_ns, info.st_ctime_ns)


def darwin_libc():
    import ctypes
    libc = ctypes.CDLL(None, use_errno=True)
    libc.acl_init.argtypes = [ctypes.c_int]
    libc.acl_init.restype = ctypes.c_void_p
    libc.acl_set_fd.argtypes = [ctypes.c_int, ctypes.c_void_p]
    libc.acl_free.argtypes = [ctypes.c_void_p]
    libc.fcopyfile.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_void_p, ctypes.c_uint32]
    return libc


def private_directory(fd):
    os.fchmod(fd, 0o700)
    if sys.platform == "darwin":
        libc = darwin_libc()
        acl = libc.acl_init(0)
        if not acl:
            raise ValueError("could not allocate private staging permissions")
        try:
            if libc.acl_set_fd(fd, acl) != 0:
                raise ValueError("could not remove inherited staging access")
        finally:
            libc.acl_free(acl)


def retain_access(source, destination, original):
    os.fchown(destination, original.st_uid, original.st_gid)
    os.fchmod(destination, stat.S_IMODE(original.st_mode))
    if sys.platform == "darwin":
        # Apple's COPYFILE_ACL | COPYFILE_XATTR is 5. Copy access metadata
        # through open descriptors, without copying data or immutable flags.
        if darwin_libc().fcopyfile(source, destination, None, 5) != 0:
            raise ValueError("could not retain environment access metadata")
    else:
        def names(fd):
            try:
                return os.listxattr(fd)
            except OSError as error:
                if error.errno in (errno.ENOTSUP, errno.EOPNOTSUPP):
                    return []
                raise
        attributes = {name: os.getxattr(source, name) for name in names(source)}
        for name in names(destination):
            if name not in attributes:
                os.removexattr(destination, name)
        for name, value in attributes.items():
            os.setxattr(destination, name, value)
        if {name: os.getxattr(destination, name) for name in names(destination)} != attributes:
            raise ValueError("could not retain environment access metadata")
    copied = os.fstat(destination)
    if (copied.st_uid, copied.st_gid, stat.S_IMODE(copied.st_mode)) != (
            original.st_uid, original.st_gid, stat.S_IMODE(original.st_mode)):
        raise ValueError("could not retain environment access permissions")


def access_env():
    root, path, operation, key = sys.argv[1:]
    if sys.platform not in ("linux", "darwin"):
        raise ValueError("environment access requires Linux, macOS, or WSL")
    if os.path.isabs(path):
        prefix = root.rstrip("/") + "/"
        if not path.startswith(prefix):
            raise ValueError("ENV_FILE must stay inside the confirmed project")
        path = path[len(prefix):]
    parts = path.split("/")
    if not parts[-1] or parts[-1] in (".", "..") or ".." in parts:
        raise ValueError("ENV_FILE must name a file without parent traversal")
    parts = [part for part in parts if part not in ("", ".")]
    if operation != "check" and not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", key):
        raise ValueError("invalid environment key")

    directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
    parent = os.dup(9)
    source = staging = None
    staging_name = None
    try:
        for part in parts[:-1]:
            child = os.open(part, directory_flags, dir_fd=parent)
            os.close(parent)
            parent = child
        leaf = parts[-1]
        try:
            source = os.open(leaf, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK,
                             dir_fd=parent)
        except FileNotFoundError:
            # A dangling symlink must not be confused with an absent file.
            try:
                os.stat(leaf, dir_fd=parent, follow_symlinks=False)
            except FileNotFoundError:
                pass
            else:
                raise ValueError("ENV_FILE changed while it was opened")
        original = os.fstat(source) if source is not None else None
        if original is not None and not stat.S_ISREG(original.st_mode):
            raise ValueError("ENV_FILE must be a regular file")
        if operation == "check":
            return 0
        content = b""
        if source is not None:
            with os.fdopen(os.dup(source), "rb") as stream:
                content = stream.read()
        lines = content.split(b"\n")
        if lines[-1] == b"":
            lines.pop()
        prefix = key.encode("ascii") + b"="
        if operation == "read":
            matches = [line[len(prefix):] for line in lines if line.startswith(prefix)]
            if not matches:
                return 1
            value = matches[-1]
            if value.startswith(b"'") and value.endswith(b"'"):
                value = value[1:-1].replace(b"'\\''", b"'")
            sys.stdout.buffer.write(value)
            return 0
        if operation != "write":
            raise ValueError("invalid environment operation")
        with os.fdopen(3, "rb", closefd=False) as stream:
            value = stream.read()
        updated = b"".join(line + b"\n" for line in lines if not line.startswith(prefix))
        updated += prefix + b"'" + value.replace(b"'", b"'\\''") + b"'\n"

        # A private directory pins the rename source even when another reader
        # can modify entries in the destination's parent directory.
        name = ".wizard-env-" + secrets.token_hex(16)
        os.mkdir(name, 0o700, dir_fd=parent)
        staging_name = name
        staging = os.open(staging_name, directory_flags, dir_fd=parent)
        private_directory(staging)
        info = os.fstat(staging)
        if info.st_uid != os.geteuid() or stat.S_IMODE(info.st_mode) != 0o700:
            raise ValueError("could not create private environment staging")
        replacement = os.open("value", os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                              0o600, dir_fd=staging)
        with os.fdopen(replacement, "wb") as stream:
            os.fchmod(stream.fileno(), 0o600)
            stream.write(updated)
            stream.flush()
            if original is not None:
                retain_access(source, stream.fileno(), original)
            os.fsync(stream.fileno())

        current = os.stat(leaf, dir_fd=parent, follow_symlinks=False) if original else None
        if original is not None and identity(current) != identity(original):
            raise ValueError("ENV_FILE changed while the update was prepared")
        if original is None:
            try:
                os.stat(leaf, dir_fd=parent, follow_symlinks=False)
            except FileNotFoundError:
                pass
            else:
                raise ValueError("ENV_FILE appeared while the update was prepared")
        os.replace("value", leaf, src_dir_fd=staging, dst_dir_fd=parent)
        return 0
    finally:
        cleanup_failed = False
        if source is not None:
            os.close(source)
        if staging is not None:
            try:
                os.unlink("value", dir_fd=staging)
            except FileNotFoundError:
                pass
            except OSError:
                cleanup_failed = True
            os.close(staging)
        if staging_name is not None:
            try:
                os.rmdir(staging_name, dir_fd=parent)
            except OSError:
                cleanup_failed = True
        os.close(parent)
        if cleanup_failed:
            print("wizard: could not remove private environment staging", file=sys.stderr)


try:
    sys.exit(access_env())
except (OSError, ValueError, AttributeError):
    # Do not include exception text, which could contain saved values.
    print("wizard: unsafe ENV_FILE or failed environment access",
          file=sys.stderr)
    sys.exit(2)
PY
}

# Revoke prior authorization before reconfiguration or after destination drift.
# FD 9 is reserved for descriptor-relative access to the confirmed root.
_revoke_destinations() {
  _WIZARD_CONFIGURED=0
  _WIZARD_ROOT=""; _WIZARD_ENV_FILE=""; _WIZARD_REPO=""
  exec 9<&-
}

# Normalize the displayed path without following or hiding symlink components.
# The descriptor-relative check rejects symlinks and unusable destinations.
_env_destination() {
  local root="$1" file="$2" relative component normalized="${1%/}"
  local -a parts
  case "$file" in ''|*/|*$'\n'*|*$'\r'*) return 1 ;; esac
  relative="$file"
  if [[ "$file" == /* ]]; then
    if [[ "$root" != / && "$file" != "$root/"* ]]; then
      warn "ENV_FILE must stay inside the confirmed project root" >&2
      return 1
    fi
    relative="${file#"${root%/}/"}"
  fi
  case "${relative##*/}" in ''|.|..) return 1 ;; esac
  IFS=/ read -r -a parts <<< "$relative"
  for component in "${parts[@]}"; do
    case "$component" in
      ..) warn "ENV_FILE must not contain parent traversal" >&2; return 1 ;;
      ''|.) ;;
      *) normalized="$normalized/$component" ;;
    esac
  done
  printf '%s' "$normalized"
}

# Call before capturing any values. An empty repo selects local-only setup.
# OWNER/REPO means github.com; HOST/OWNER/REPO supports explicit other hosts.
configure_destinations() {
  local root="${1:-}" repo="${2:-}" file reply="" rc
  _revoke_destinations
  [[ -n "$root" ]] || { warn "Specify the project root" >&2; return 1; }
  [[ "$root" == /* ]] || root="$PWD/$root"
  root=$(cd -P -- "$root" && printf '%s/.' "$PWD") || return 1
  root="${root%/.}"
  case "$root" in *$'\n'*|*$'\r'*) return 1 ;; esac
  file=$(_env_destination "$root" "$ENV_FILE") || return 1
  if [[ -n "$repo" ]]; then
    [[ "$repo" == */*/* ]] || repo="github.com/$repo"
    if [[ ! "$repo" =~ ^[A-Za-z0-9][A-Za-z0-9.-]*/[A-Za-z0-9][A-Za-z0-9-]*/[A-Za-z0-9_.-]+$ || "${repo##*/}" == . || "${repo##*/}" == .. ]]; then
      warn "Specify GitHub repository as [HOST/]OWNER/REPO" >&2
      return 1
    fi
  fi
  command -v python3 >/dev/null 2>&1 || {
    printf 'wizard: Python 3 is required for safe environment-file access\n' >&2
    return 2
  }
  # Pin the displayed directory before waiting for input, without reading values.
  _WIZARD_ROOT="$root"; _WIZARD_ENV_FILE="$file"; _WIZARD_REPO="$repo"
  if ! exec 9< "$root"; then _revoke_destinations; return 2; fi
  printf '\n  Project root: %q\n  Env file:     %q\n' "$root" "$file"
  printf '  GitHub repo:  %s\n' "${repo:-none (local-only)}"
  printf '  Use these destinations? [y/N] '
  read -r reply || { _revoke_destinations; return 1; }
  case "$reply" in y|Y|yes|YES|Yes) ;; *) _revoke_destinations; return 1 ;; esac
  ENV_FILE="$file"
  _env_file check || { rc=$?; _revoke_destinations; return "$rc"; }
  _WIZARD_CONFIGURED=1
}

# Recheck before every operation; a changed destination needs fresh consent.
_require_destinations() {
  local rc
  if [[ "$_WIZARD_CONFIGURED" != 1 || "$ENV_FILE" != "$_WIZARD_ENV_FILE" ]]; then
    _revoke_destinations
    warn "Call configure_destinations before capturing or persisting values" >&2
    return 2
  fi
  _env_file check || { rc=$?; _revoke_destinations; return "$rc"; }
}

# _existing KEY: last saved value, with write_env's quoting undone.
_existing() {
  _env_file read "$1"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  _require_destinations || return "$?"
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key") || { rc=$?; (( rc == 1 )) || return "$rc"; rc=0; }
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  _require_destinations || return "$?"
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key") || { rc=$?; (( rc == 1 )) || return "$rc"; rc=0; }
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. New files use mode 0600. Existing access permissions are
# retained, but atomic replacement changes the inode and breaks hard links.
# Symlinked destinations and paths outside the confirmed project are refused.
write_env() {
  _require_destinations || return "$?"
  local key="$1" value="$2" destination
  printf '%s' "$value" | _env_file write "$key" || return "$?"
  printf -v destination '%s → %q' "$key" "$ENV_FILE"
  WRITTEN_ENV+=("$destination")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  _require_destinations || return "$?"
  local name="$1" value="$2"
  if [[ -z "$_WIZARD_REPO" ]]; then
    SKIPPED+=("GitHub secret $name (no repository confirmed)")
    warn "skipped GitHub secret $name: no repository confirmed"
    return 0
  fi
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" --repo "$_WIZARD_REPO" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name → $_WIZARD_REPO")
      printf '  %s✓ set%s GitHub secret %s → %s\n' "$GREEN" "$RESET" "$name" "$_WIZARD_REPO"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name --repo $_WIZARD_REPO)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  _require_destinations || return "$?"
  local name="$1" value="$2"
  if [[ -z "$_WIZARD_REPO" ]]; then
    SKIPPED+=("GitHub variable $name (no repository confirmed)")
    warn "skipped GitHub variable $name: no repository confirmed"
    return 0
  fi
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" --repo "$_WIZARD_REPO" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s → %s\n' "$GREEN" "$RESET" "$name" "$_WIZARD_REPO"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  local s
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  if (( ${#WRITTEN_ENV[@]} )); then
    note "wrote ${#WRITTEN_ENV[@]} value(s):"
    for s in "${WRITTEN_ENV[@]}"; do note "  - $s"; done
  fi
  if (( ${#WRITTEN_SECRET[@]} )); then
    note "set ${#WRITTEN_SECRET[@]} GitHub secret(s):"
    for s in "${WRITTEN_SECRET[@]}"; do note "  - $s"; done
  fi
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=1

# Author the intended root and repository here. Without a repo, writes stay local.
configure_destinations "${PROJECT_ROOT:-.}" "${WIZARD_GITHUB_REPO:-}"
banner "Stripe setup"

# ── Example stage: replace with your real steps ───────────────────────────
stage "Stripe: API keys"
say "We'll grab your Stripe test keys and store them for local dev + CI."
open_url "https://dashboard.stripe.com/test/apikeys"
step "On the API keys page, copy the Publishable key (starts pk_test_)."
ask STRIPE_PUBLISHABLE_KEY "Paste the publishable key:"
step "Click 'Reveal test key' on the Secret key row, then copy it."
ask_secret STRIPE_SECRET_KEY "Paste the secret key:"
write_env STRIPE_PUBLISHABLE_KEY "$STRIPE_PUBLISHABLE_KEY"
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
set_secret STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"   # CI needs this one
# ──────────────────────────────────────────────────────────────────────────

finish
